import json
from pathlib import Path


def write_report(payload, path: Path):
    content = json.dumps(payload, ensure_ascii=False, allow_nan=False).replace(
        "<", "\\u003c"
    )
    path.write_text(HTML.replace("__DATA__", content), encoding="utf-8")


HTML = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Engine Prognostics Lab</title><style>
*{box-sizing:border-box}body{margin:0;font:15px/1.6 system-ui,sans-serif;background:#f1f5f8;color:#163349}main{max-width:1400px;margin:auto;padding:28px}h1{font-size:34px;margin:0}h2{font-size:21px;margin:0 0 10px}p{margin:8px 0}.eyebrow{font-size:12px;letter-spacing:.1em;color:#007c80;font-weight:750}.muted,small{color:#526b7c}.note{background:#fff6e7;border-left:4px solid #da9c3a;padding:14px;margin:18px 0}.controls{display:flex;flex-wrap:wrap;gap:20px;align-items:end;margin:22px 0}label{display:flex;flex-direction:column;gap:7px;font-size:13px;font-weight:650}select,button,input{font:inherit;max-width:100%;min-height:42px}select,button{padding:8px 12px;border:1px solid #b3c8d2;border-radius:6px;background:white;color:#163349}button{background:#087b80;color:white;cursor:pointer}button:focus-visible,select:focus-visible{outline:3px solid #da9c3a}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:20px}.card,.panel{background:white;border:1px solid #d9e4ea;border-radius:12px;padding:20px;min-width:0}.card strong{font-size:27px;display:block}.card span{font-size:13px;color:#526b7c}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.panel{margin-bottom:20px}.grid .panel{margin:0 0 20px}.wrap{overflow:auto;max-height:460px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:10px 9px;border-bottom:1px solid #d9e4ea;white-space:nowrap}th{background:#f4f8fa;position:sticky;top:0}svg{width:100%;height:auto;display:block}svg text{font:12px system-ui,sans-serif;fill:#526b7c}a{color:#007780}footer{font-size:12px;color:#526b7c;padding-bottom:20px}.chart-caption{font-size:12px;color:#526b7c}@media(max-width:900px){.grid{grid-template-columns:minmax(0,1fr)}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:16px}h1{font-size:28px}}@media(max-width:450px){.card,.panel{padding:14px}.card strong{font-size:23px}.controls label{width:100%}}
</style></head><body><main><header><div class="eyebrow">AEROSPACE / PREDICTIVE MAINTENANCE RESEARCH</div><h1>Engine Prognostics Lab</h1><p>Operating-regime normalization, degradation features and remaining useful life estimates.</p><p class="muted">NASA C-MAPSS · all selected subsets evaluated on official terminal test cycles · offline report</p><div class="note">These are <strong>simulated turbofan trajectories</strong>, not measurements from an operating airline. Predictions are benchmark estimates in cycles, not a maintenance authorization or an airworthiness assessment.</div></header>
<div class="controls"><label>Benchmark subset<select id="subset"></select></label><label>Review horizon: <span id="horizon-value">30 cycles</span><input id="horizon" type="range" min="10" max="80" step="5" value="30"></label><button id="export">Download predictions CSV</button></div><div id="cards" class="cards" aria-live="polite"></div>
<div class="grid"><section class="panel"><h2>Official test: predicted vs actual life</h2><svg id="scatter" viewBox="0 0 600 460" role="img" aria-label="Predicted and actual remaining useful life scatter plot"></svg><p class="chart-caption">One point per held-out test engine, at its last supplied cycle. Dashed line = perfect prediction. Point predictions are capped at the training target ceiling; official truth is uncapped. Hover for values.</p></section><section class="panel"><h2>Engine review screen</h2><p id="review"></p><p class="muted">Flag an engine when its prediction interval's lower bound is at or below the selected horizon. This is a conservative review rule, not an optimized replacement policy. False positives and misses are evaluated retrospectively using benchmark labels.</p><div class="wrap"><table><thead><tr><th>Engine</th><th>Cycle</th><th>Predicted</th><th>Interval</th><th>Actual</th><th>Review</th></tr></thead><tbody id="engines"></tbody></table></div></section></div>
<div class="grid"><section class="panel"><h2>Visible degradation history</h2><label>Example test engine<select id="trajectory-select"></select></label><svg id="trajectory" viewBox="0 0 600 400" role="img" aria-label="Causal prediction history and retrospective truth"></svg><p class="chart-caption">Fixed first three test engines, sampled every five cycles. Teal = prediction from the observed prefix; dashed = retrospective actual RUL. Examples are selected by ID, not by favorable performance. No future observations are used in features.</p></section><section class="panel"><h2>Engine-separated validation</h2><p id="split"></p><div class="wrap"><table><thead><tr><th>Candidate</th><th>Validation MAE</th><th>Official test MAE</th><th>Official test RMSE</th></tr></thead><tbody id="candidates"></tbody></table></div><p id="interval"></p><p class="muted">A single pre-failure endpoint per calibration engine supplies an absolute-error score. The 80% split-conformal level is nominal under exchangeability; the official truncation mechanism can differ. Empirical coverage and width are reported instead of promising guaranteed coverage.</p></section></div>
<section class="panel"><h2>Method and reproducibility</h2><p id="method"></p><p>Only fitting engines determine operating-regime clusters, normalization statistics, rolling-feature inputs and model coefficients. Validation engines choose among age baseline, Ridge and histogram gradient boosting. Calibration engines set interval width. Official test labels are used after selection and calibration for reporting, not training. No random row-level split or internal row-level early stopping is used.</p><p>Trailing sensor means, standard deviations and slopes use a 20-cycle window, resetting at engine boundaries. Training rows receive equal total weight per engine. Uncapped and clipped-target scores are saved separately. Errors overestimating remaining life incur a stronger asymmetric benchmark penalty; no financial maintenance savings are inferred.</p><p><a id="model-link">Download fitted model</a> · <a href="results.json">Full metrics and provenance</a> · <a href="predictions.csv">All terminal predictions</a></p></section>
<footer>Source: <a href="https://data.nasa.gov/dataset/cmapss-jet-engine-simulated-data">NASA C-MAPSS Jet Engine Simulated Data</a>. Reference: Saxena, Goebel, Simon and Eklund, <em>Damage Propagation Modeling for Aircraft Engine Run-to-Failure Simulation</em>, PHM 2008. Source files are retrieved separately and excluded from Git. Benchmark IDs refer to simulated units.</footer></main>
<script type="application/json" id="data">__DATA__</script><script>
'use strict';const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),fmt=v=>v===null?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:2});function node(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;}function row(body,values){const r=node('tr');values.forEach(v=>r.append(node('td',v)));body.append(r);}function option(target,text,value=text){const o=node('option',text);o.value=value;target.append(o);}const ns='http://www.w3.org/2000/svg';function s(tag,attrs,text){const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;return e;}Object.keys(D.subsets).forEach(k=>option($('subset'),k));function current(){return D.subsets[$('subset').value];}
function axes(svg,xLabel,yLabel,maxX,maxY,height=460){svg.replaceChildren();const x=v=>60+v/maxX*510,y=v=>height-55-v/maxY*(height-95);svg.append(s('path',{d:`M 60 40 V ${height-55} H 570`,stroke:'#a0b5c0',fill:'none'}));for(let i=0;i<=4;i++){let xx=maxX*i/4,yy=maxY*i/4;svg.append(s('text',{x:x(xx),y:height-32,'text-anchor':'middle'},Math.round(xx)));svg.append(s('text',{x:49,y:y(yy)+4,'text-anchor':'end'},Math.round(yy)));}svg.append(s('text',{x:315,y:height-5,'text-anchor':'middle'},xLabel));svg.append(s('text',{x:60,y:20},yLabel));return {x,y};}
function scatter(){const data=current().predictions,max=Math.max(150,...data.map(p=>Math.max(p.rul_actual,p.rul_predicted)))*1.05,{x,y}=axes($('scatter'),'Actual RUL (cycles)','Predicted RUL (cycles)',max,max);$('scatter').append(s('path',{d:`M ${x(0)} ${y(0)} L ${x(max)} ${y(max)}`,stroke:'#8ba3af','stroke-dasharray':'6 5'}));data.forEach(p=>{const c=s('circle',{cx:x(p.rul_actual),cy:y(p.rul_predicted),r:3.5,fill:'#087f86','fill-opacity':.65});c.append(s('title',{},`Engine ${p.engine}: actual ${fmt(p.rul_actual)}, predicted ${fmt(p.rul_predicted)}`));$('scatter').append(c);});}
function history(){const examples=current().trajectories,item=examples[Number($('trajectory-select').value)],points=item.points,maxX=Math.max(...points.map(p=>p.cycle))*1.02,maxY=Math.max(150,...points.map(p=>Math.max(p.actual,p.prediction)))*1.04,{x,y}=axes($('trajectory'),'Observed cycles','Remaining life (cycles)',maxX,maxY,400);for(const [key,color,dash] of [['actual','#8ba3af','6 4'],['prediction','#087f86','']]){const d=points.map((p,i)=>`${i?'L':'M'} ${x(p.cycle)} ${y(p[key])}`).join(' ');$('trajectory').append(s('path',{d,fill:'none',stroke:color,'stroke-width':2.5,'stroke-dasharray':dash}));}}
function review(){const horizon=Number($('horizon').value),pred=current().predictions;$('horizon-value').textContent=horizon+' cycles';let tp=0,fp=0,fn=0,flags=0;$('engines').replaceChildren();pred.forEach(p=>{const flag=p.lower<=horizon,actual=p.rul_actual<=horizon;if(flag)flags++;if(flag&&actual)tp++;if(flag&&!actual)fp++;if(!flag&&actual)fn++;row($('engines'),[p.engine,p.cycle,fmt(p.rul_predicted),`${fmt(p.lower)}–${fmt(p.upper)}`,fmt(p.rul_actual),flag?'Review':'—']);});$('review').textContent=`${flags} / ${pred.length} flagged at ${horizon} cycles: ${tp} true positives, ${fp} false positives and ${fn} missed imminent cases. Precision ${tp+fp?fmt(100*tp/(tp+fp))+'%':'undefined'}; recall ${tp+fn?fmt(100*tp/(tp+fn))+'%':'undefined'}.`;}
function render(){const d=current(),m=d.metrics;$('cards').replaceChildren();[['Official test engines',m.test.engines],['Test RMSE · cycles',fmt(m.test.rmse)],['Test MAE · cycles',fmt(m.test.mae)],['Empirical interval coverage',fmt(100*m.interval.empirical_test_coverage)+'%']].forEach(([label,value])=>{const c=node('div');c.className='card';c.append(node('strong',value),node('span',label));$('cards').append(c);});$('split').textContent=`${m.train_engines} run-to-failure training engines: ${m.split.fit.length} fit / ${m.split.validation.length} validation / ${m.split.calibration.length} calibration. ${m.test_engines} separate official test engines. Selected: ${m.selected_model}.`;$('candidates').replaceChildren();Object.entries(m.validation).forEach(([name,v])=>row($('candidates'),[name,fmt(v.mae),fmt(m.test_comparison[name].mae),fmt(m.test_comparison[name].rmse)]));$('interval').textContent=`Nominal coverage ${fmt(100*m.interval.nominal_coverage)}%; calibration radius ${fmt(m.interval.radius)} cycles; mean test interval width ${fmt(m.interval.mean_width)} cycles. Training target ceiling: ${m.training_rul_cap}; official test targets remain uncapped.`;$('method').textContent=`${m.regimes} fitted operating regimes; ${m.feature_count} features; seed ${m.seed}. Validation endpoint fractions 35%–85%. Official asymmetric score ${fmt(m.test.asymmetric_score)} (lower is better, not comparable across different engine counts).`;$('model-link').href=D.provenance.model_links[m.subset];$('trajectory-select').replaceChildren();d.trajectories.forEach((t,i)=>option($('trajectory-select'),'Engine '+t.engine,String(i)));scatter();history();review();}
$('subset').addEventListener('change',render);$('horizon').addEventListener('input',review);$('trajectory-select').addEventListener('change',history);$('export').addEventListener('click',()=>{const rows=[['engine','cycle','actual_rul','predicted_rul','lower','upper','review_flag']];current().predictions.forEach(p=>rows.push([p.engine,p.cycle,p.rul_actual,p.rul_predicted,p.lower,p.upper,p.lower<=Number($('horizon').value)]));const url=URL.createObjectURL(new Blob([rows.map(r=>r.join(',')).join('\r\n')],{type:'text/csv'})),a=node('a');a.href=url;a.download=$('subset').value+'_predictions.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});render();
</script></body></html>"""
